<?php

namespace SwanFlutter\LaravelApiSnapshot\Console;

use Illuminate\Console\Command;
use SwanFlutter\LaravelApiSnapshot\Testing\TestEnvironment;

/**
 * Prepares the application for the tests generated by api-snapshot:tests:
 * an isolated test database, the env values phpunit runs with, the seeders and
 * the authenticator the generated tests read from config.
 */
class SnapshotInstallTestingCommand extends Command
{
    protected $signature = 'api-snapshot:install-testing
        {--connection= : Test database connection (default: sqlite)}
        {--database=   : Test database name (default: :memory:)}
        {--db-file=    : Use this SQLite file instead of :memory: and create it when missing}
        {--seeders=    : Comma-separated seeder classes to run before each test}
        {--authenticator= : Class that signs a test in for a protected endpoint}
        {--with-authenticator-stub : Write a starter authenticator into tests/Support}
        {--publish     : Publish config/api-snapshot.php so the settings above can be stored}
        {--no-env      : Do not write .env.testing}
        {--no-phpunit  : Do not touch phpunit.xml}
        {--dry-run     : Report the changes without writing anything}
        {--force       : Replace values that are already set}';

    protected $description = 'Configure the test database, seeders and authenticator used by the generated snapshot tests';

    public function handle(): int
    {
        $this->components->info('Laravel API Snapshot — test environment setup');

        $environment = new TestEnvironment(
            base_path(),
            (bool) $this->option('force'),
            (bool) $this->option('dry-run'),
        );

        $connection = (string) ($this->option('connection') ?: 'sqlite');
        $database   = (string) ($this->option('database') ?: ':memory:');

        if ($file = $this->option('db-file')) {
            $database = (string) $file;
        }

        $values = TestEnvironment::defaults($connection, $database);

        if ($key = $this->currentAppKey()) {
            $values['APP_KEY'] = $key;
        }

        if ($this->option('publish')) {
            $this->callSilently('vendor:publish', ['--tag' => 'api-snapshot-config', '--force' => true]);
        }

        $changes = [];

        if (! $this->option('no-env')) {
            $changes = array_merge($changes, $environment->patchEnv($values));
        }

        if (! $this->option('no-phpunit')) {
            $changes = array_merge($changes, $environment->patchPhpUnit($values));
        }

        if ($file = $this->option('db-file')) {
            $changes = array_merge($changes, $environment->createSqliteFile((string) $file));
        }

        $changes = array_merge($changes, $environment->patchConfig(
            $this->csv((string) $this->option('seeders')),
            is_string($this->option('authenticator')) ? (string) $this->option('authenticator') : null,
        ));

        if ($this->option('with-authenticator-stub')) {
            $changes = array_merge($changes, $environment->writeAuthenticatorStub());
        }

        $this->report($changes);

        return self::SUCCESS;
    }

    /** @param  list<string>  $changes */
    private function report(array $changes): void
    {
        if ($changes === []) {
            $this->components->info('The test environment is already configured; nothing changed.');
        }

        foreach (array_unique($changes) as $change) {
            $this->components->twoColumnDetail('<fg=green>✔</>', $change);
        }

        $this->newLine();
        $this->line('  Next: <options=bold>php artisan api-snapshot:tests</>');
    }

    /** @return list<string> */
    private function csv(string $value): array
    {
        return array_values(array_filter(array_map('trim', explode(',', $value)), fn ($item) => $item !== ''));
    }

    private function currentAppKey(): ?string
    {
        $key = (string) config('app.key', '');

        if ($key !== '') {
            return $key;
        }

        $env = base_path('.env');

        if (! is_readable($env)) {
            return null;
        }

        foreach (file($env, FILE_IGNORE_NEW_LINES) ?: [] as $line) {
            if (preg_match('/^\s*APP_KEY\s*=\s*(.+)$/i', (string) $line, $m) === 1) {
                return trim($m[1], " \"'");
            }
        }

        return null;
    }
}
